// Generates src/lib/template-db.ts: an empty SQLite database with the current
// Prisma schema, embedded as base64. Used in cloud mode to create a fresh
// folio.db in the user's Google Drive on first login.
//
// Run `npm run db:template` after every prisma/schema.prisma change and
// commit the regenerated file.

import { execSync } from 'child_process'
import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const tmpDb = path.join(root, 'prisma', '.template.db')

fs.rmSync(tmpDb, { force: true })

execSync('npx prisma db push --skip-generate', {
    cwd: root,
    stdio: 'inherit',
    env: { ...process.env, DATABASE_URL: 'file:./.template.db' },
})

const b64 = fs.readFileSync(tmpDb).toString('base64')
fs.rmSync(tmpDb, { force: true })

const out = path.join(root, 'src', 'lib', 'template-db.ts')
fs.writeFileSync(
    out,
    `// AUTO-GENERATED by scripts/generate-template-db.mjs — do not edit.\n` +
    `// Regenerate with \`npm run db:template\` after schema changes.\n` +
    `export const TEMPLATE_DB_BASE64 =\n    '${b64}'\n`
)

console.log(`Wrote ${out} (${(b64.length / 1024).toFixed(1)} KB base64)`)
